function limpa_formulário_cep(){$("#Endereco").val("");$("#Bairro").val("");$("#Cidade").val("");$("#Estado").val("")}function validarCPF(n){var i,r,u,t,f;if((n=n.replace(/\D/g,""),n.length!==11)||(i=[...n].map(Number),i.every(n=>n===i[0])))return!1;for(r=0,t=0;t<9;t++)r+=i[t]*(10-t);for(u=r*10%11,u===10&&(u=0),r=0,t=0;t<10;t++)r+=i[t]*(11-t);return(f=r*10%11,f===10&&(f=0),u!==i[9]||f!==i[10])?!1:!0}function validarCNPJ(n){if((n=n.replace(/[^\d]+/g,""),n.length!==14)||/^(\d)\1{13}$/.test(n))return!1;let i=0,t=5;for(let r=0;r<12;r++)i+=n.charAt(r)*t,t=t===2?9:t-1;let r=i%11,u=r<2?0:11-r;if(n.charAt(12)!=u)return!1;i=0;t=6;for(let r=0;r<13;r++)i+=n.charAt(r)*t,t=t===2?9:t-1;r=i%11;let f=r<2?0:11-r;return n.charAt(13)!=f?!1:!0}function printDiv(n){var t=document.getElementById(n).innerHTML,i=document.body.innerHTML;document.body.innerHTML=t;window.print();document.body.innerHTML=i}async function carregarMunicipios(n){try{const i=await fetch(`https://servicodados.ibge.gov.br/api/v1/localidades/estados/${n}/municipios`);if(!i.ok)throw new Error("Erro ao carregar municípios");const t=await i.json();for(let n=0;n<t.length;n++)t[n].nome=t[n].nome.normalize("NFD").replace(/[\u0300-\u036f]/g,"");return t.sort((n,t)=>n.nome.localeCompare(t.nome))}catch(t){console.error("Erro:",t);throw t;}}function initializeTemporaryAlerts(n=5e3){$(".temporary-alert").each(function(){const t=$(this);setTimeout(function(){t.fadeOut(500,function(){$(this).remove()})},n)})}$(document).ready(function(){$("#open-sidebar").click(()=>{$("#sidebar").addClass("active"),$("#sidebar-overlay").removeClass("d-none")});$("#sidebar-overlay").click(function(){$("#sidebar").removeClass("active");$(this).addClass("d-none")});$("#CNPJ_Corretora").on("input",function(){let n=$(this).val();n=n.replace(/\D/g,"");n=n.substring(0,14);n=n.replace(/^(\d{2})(\d{3})(\d{3})(\d{4})(\d{2})?$/,"$1.$2.$3/$4-$5");$(this).val(n)});var n=!1;$("#CEP").blur(function(){var t=$(this).val().replace(/\D/g,""),i;t!=""?(i=/^[0-9]{8}$/,i.test(t)?($("#Endereco").val("..."),$("#Bairro").val("..."),$("#Cidade").val("..."),$("#Estado").val("..."),$.getJSON("https://viacep.com.br/ws/"+t+"/json/?callback=?",function(t){"erro"in t?(limpa_formulário_cep(),n||(alert("CEP não encontrado."),n=!0)):($("#Endereco").val(t.logradouro),$("#Bairro").val(t.bairro),$("#Cidade").val(t.localidade),$("#Estado").val(t.uf),n=!1)})):n||(alert("Formato de CEP inválido."),n=!0)):limpa_formulário_cep()})});